}
.controls-note { display: flex; gap: 12px; align-items: center; }
.controls-note b { color: #918a79; letter-spacing: .16em; }

@media (max-width: 980px) {
  .menu-main { grid-template-columns: 1fr; gap: 20px; align-items: start; padding-top: 14px; }
  .hero h1 { font-size: clamp(50px, 11vw, 86px); margin-bottom: 18px; }
