  .card-foot { display: none; }
}

/* ============================================================ HUD */
#hud { position: fixed; inset: 0; z-index: 10; pointer-events: none; }
#hud button, #hud #joystick, #hud #quickbar { pointer-events: auto; }
.hud-top { position: absolute; top: max(12px, env(safe-area-inset-top)); left: 14px; right: 14px; display: flex; align-items: flex-start; gap: 12px; }
.glass {
  background: linear-gradient(160deg, rgba(19, 22, 17, .88), rgba(14, 17, 13, .76));
  border: 1px solid rgba(219, 203, 168, .15);
  box-shadow: 0 8px 24px rgba(0,0,0,.24);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
.char-panel { display: flex; gap: 10px; padding: 9px 11px 9px 9px; min-width: 304px; position: relative; }
.portrait {
  width: 47px; height: 55px; flex: 0 0 auto;
  border: 1px solid rgba(213,160,74,.45);
  background: radial-gradient(circle at 45% 32%, #79674e 0 14%, transparent 15%), linear-gradient(150deg, #31372c, #171b15);
  display: grid; place-items: center;
  font-family: var(--serif); font-size: 22px; color: #d6bd8e;
  position: relative; overflow: hidden;
}
.portrait::after { content: ""; position: absolute; inset: 0; background: repeating-linear-gradient(0deg, transparent 0 2px, rgba(0,0,0,.14) 2px 3px); }
.char-main { flex: 1; min-width: 0; }
.char-name-row { display: flex; align-items: baseline; gap: 8px; margin-bottom: 6px; }
.char-name-row > span:first-child { font: 700 12px/1 var(--sans); letter-spacing: .05em; color: #e9e1cf; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 140px; }
.prof-tag { font: 7px/1 var(--mono); letter-spacing: .1em; color: var(--amber); border: 1px solid rgba(213,160,74,.3); padding: 3px 4px; white-space: nowrap; }
.health-line { display: flex; align-items: center; gap: 6px; margin-bottom: 5px; }
.bar-label { display: flex; align-items: center; gap: 3px; font: 7px/1 var(--mono); letter-spacing: .08em; color: #948c7a; }
.bar-label svg { width: 10px; height: 10px; color: #b65a48; }
.mini-bar { height: 5px; background: rgba(0,0,0,.55); flex: 1; overflow: hidden; border: 1px solid rgba(255,255,255,.05); }
.mini-bar i { display: block; height: 100%; width: 100%; transition: width .3s; }
.health-line b { font: 8px/1 var(--mono); color: #c5bca8; min-width: 18px; text-align: right; }
.health .health { background: linear-gradient(90deg, #7e2d27, #c35a45); }
#healthBar { background: linear-gradient(90deg, #7d2d26, #cd5b48); }
.needs-mini { display: flex; gap: 8px; }
.need-mini { display: flex; align-items: center; gap: 4px; flex: 1; }
.need-mini svg { width: 10px; height: 10px; color: #8d8674; flex: 0 0 auto; }
.need-mini .mini-bar { height: 4px; }
.hunger i { background: linear-gradient(90deg, #795f2e, #c49a45); }
.thirst i { background: linear-gradient(90deg, #345f72, #6da2b8); }
.sleep i { background: linear-gradient(90deg, #554b75, #9184b4); }
.stamina i { background: linear-gradient(90deg, #506b3b, #8fa95c); }
.status-chips { position: absolute; left: 58px; bottom: -20px; display: flex; gap: 4px; z-index: 2; }
.status-chip { font: 7px/1 var(--mono); letter-spacing: .04em; padding: 4px 6px; background: rgba(20,22,17,.9); border: 1px solid; }
.status-chip.bleed { color: #e07862; border-color: rgba(196,85,68,.5); }
.status-chip.cold { color: #8db9cf; border-color: rgba(109,154,174,.5); }
.status-chip.infect { color: #c1a958; border-color: rgba(193,169,88,.5); }
.status-chip.pain { color: #c58c9c; border-color: rgba(197,140,156,.5); }
.status-chip.wet { color: #8fa9b0; border-color: rgba(143,169,176,.4); }

.clock-panel { margin: 0 auto; padding: 10px 16px; min-width: 235px; text-align: center; }
.location { display: flex; align-items: center; justify-content: center; gap: 5px; font: 10px/1 var(--sans); letter-spacing: .08em; color: #e0d7c3; margin-bottom: 6px; }
.location svg { width: 12px; height: 12px; color: var(--amber); }
.clock-row { display: flex; align-items: center; justify-content: center; gap: 8px; font: 9px/1 var(--mono); letter-spacing: .1em; color: #9b9482; }
#clockTime { font: 700 15px/1 var(--mono); color: #eee5d2; letter-spacing: .02em; }
.clock-sep { width: 1px; height: 11px; background: var(--line-strong); }
.weather-pill { display: flex; align-items: center; gap: 4px; border-left: 1px solid var(--line); padding-left: 8px; }
.weather-pill svg { width: 13px; height: 13px; color: var(--amber); }
.weather-pill b { color: #c9c0aa; font-weight: normal; }

.top-actions { margin-left: auto; display: flex; gap: 5px; align-items: flex-start; }
.icon-btn {
  min-width: 48px; height: 48px; padding: 5px 7px;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px;
  background: linear-gradient(160deg, rgba(19,22,17,.9), rgba(14,17,13,.8));
  border: 1px solid rgba(219,203,168,.14); color: #a8a08d;
  transition: border-color .15s, color .15s, background .15s;
}
.icon-btn svg { width: 18px; height: 18px; }
.icon-btn span { font: 6.5px/1 var(--mono); letter-spacing: .05em; }
.icon-btn:hover { border-color: rgba(213,160,74,.6); color: var(--amber-bright); background: rgba(213,160,74,.08); }
.menu-btn { min-width: 40px; }
.menu-btn span { display: none; }

#objectiveTracker {
  position: absolute; top: 92px; left: 14px; width: 240px; padding: 9px 11px;
  border-left: 2px solid rgba(213,160,74,.6);
}
.obj-head { display: flex; justify-content: space-between; font: 7px/1 var(--mono); letter-spacing: .18em; color: var(--amber); margin-bottom: 6px; }
.obj-head span:last-child { color: #7c7768; }
#objText { font-size: 10.5px; line-height: 1.4; color: #cfc7b4; margin-bottom: 7px; }
.obj-bar { height: 2px; background: rgba(255,255,255,.08); }
.obj-bar i { display: block; height: 100%; width: 12%; background: var(--amber); transition: width .4s; }

#prompt {
  position: absolute; left: 50%; bottom: 182px; transform: translateX(-50%);
  background: rgba(14,17,13,.94); border: 1px solid rgba(213,160,74,.45);
  padding: 9px 15px 9px 9px; display: flex; align-items: center; gap: 9px;
  font-size: 11px; letter-spacing: .03em; color: #e6ddc9; white-space: nowrap;
  box-shadow: 0 8px 22px rgba(0,0,0,.35); pointer-events: none;
  animation: promptIn .18s ease-out;
}
#prompt .key {
  width: 23px; height: 23px; display: grid; place-items: center;
  background: var(--amber); color: #191910; font: 700 10px/1 var(--mono);
}
@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 5px); } }

#toasts { position: absolute; top: 88px; right: 15px; width: 275px; display: flex; flex-direction: column; gap: 6px; align-items: flex-end; }
.toast {
  max-width: 100%; padding: 9px 12px;
  background: linear-gradient(150deg, rgba(24,27,21,.96), rgba(14,17,13,.94));
  border: 1px solid rgba(219,203,168,.18); border-left: 2px solid var(--amber);
  color: #cec6b3; font-size: 10.5px; line-height: 1.4; box-shadow: 0 6px 18px rgba(0,0,0,.3);
  animation: toastIn .2s ease-out, toastOut .35s 3.65s forwards;
}
.toast b { color: var(--amber-bright); font-weight: bold; }
.toast.good { border-left-color: var(--green); }
.toast.bad { border-left-color: var(--red); }
@keyframes toastIn { from { opacity: 0; transform: translateX(14px); } }
@keyframes toastOut { to { opacity: 0; transform: translateX(10px); } }

#joystick {
  position: absolute; left: max(18px, env(safe-area-inset-left)); bottom: max(72px, calc(env(safe-area-inset-bottom) + 62px));
  width: 126px; display: flex; flex-direction: column; align-items: center; gap: 5px;
}
.joy-ring {
  width: 118px; height: 118px; border-radius: 50%;
  border: 1px solid rgba(219,203,168,.26);
  background: radial-gradient(circle, rgba(19,22,17,.56) 0 42%, rgba(19,22,17,.22) 43% 100%);
  position: relative; touch-action: none;
  box-shadow: inset 0 0 30px rgba(0,0,0,.25);
}
.joy-ring::before { content: ""; position: absolute; inset: 15px; border-radius: 50%; border: 1px dashed rgba(219,203,168,.13); }
.joy-knob {
  position: absolute; left: 50%; top: 50%; width: 48px; height: 48px; margin: -24px 0 0 -24px;
  border-radius: 50%; border: 1px solid rgba(240,193,108,.62);
  background: radial-gradient(circle at 35% 30%, rgba(213,160,74,.42), rgba(28,31,24,.88));
  box-shadow: 0 4px 14px rgba(0,0,0,.4); transition: box-shadow .1s;
}
.joy-ring.active .joy-knob { box-shadow: 0 0 22px rgba(213,160,74,.25); }
.joy-tick { position: absolute; width: 5px; height: 5px; border-top: 1px solid rgba(219,203,168,.5); border-left: 1px solid rgba(219,203,168,.5); }
.joy-tick.n { top: 7px; left: 50%; transform: translateX(-50%) rotate(45deg); }
.joy-tick.e { right: 7px; top: 50%; transform: translateY(-50%) rotate(135deg); }
.joy-tick.s { bottom: 7px; left: 50%; transform: translateX(-50%) rotate(225deg); }
.joy-tick.w { left: 7px; top: 50%; transform: translateY(-50%) rotate(-45deg); }
#joystick small { font: 7px/1 var(--mono); letter-spacing: .2em; color: #797465; }

#actionPad { position: absolute; right: max(15px, env(safe-area-inset-right)); bottom: max(66px, calc(env(safe-area-inset-bottom) + 56px)); width: 158px; height: 158px; }
.act-btn {
  position: absolute; border-radius: 50%; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 2px;
  border: 1px solid rgba(219,203,168,.27); color: #e7dfcb;
  background: radial-gradient(circle at 40% 30%, rgba(55,61,47,.9), rgba(17,20,15,.92));
  box-shadow: 0 5px 14px rgba(0,0,0,.32), inset 0 1px 0 rgba(255,255,255,.05);
  touch-action: none; transition: transform .08s, border-color .15s, background .15s;
}
.act-btn svg { width: 22px; height: 22px; }
.act-btn span { font: 6.5px/1 var(--mono); letter-spacing: .04em; color: #a49c88; }
.act-btn:active, .act-btn.pressed { transform: scale(.93); border-color: var(--amber-bright); }
.act-btn.attack {
  width: 76px; height: 76px; right: 0; bottom: 0;
  border-color: rgba(196,85,68,.65);
  background: radial-gradient(circle at 40% 30%, rgba(111,47,38,.74), rgba(23,19,16,.94));
  color: #f0a28f;
  box-shadow: 0 0 0 5px rgba(196,85,68,.08), 0 8px 20px rgba(0,0,0,.4);
}
.act-btn.attack svg { width: 31px; height: 31px; }
.act-btn.interact { width: 56px; height: 56px; right: 79px; bottom: 13px; border-color: rgba(213,160,74,.45); }
.act-btn.interact svg { width: 21px; height: 21px; }
.act-btn.small { width: 42px; height: 42px; }
.act-btn.small svg { width: 16px; height: 16px; }
.act-btn.small span { display: none; }
#btnSprint { right: 10px; bottom: 88px; }
#btnCrouch { right: 52px; bottom: 95px; }
#btnCrouch.active { border-color: var(--amber); color: var(--amber-bright); background: rgba(213,160,74,.17); }
#btnSprint.active { border-color: var(--amber); color: var(--amber-bright); }
#btnAttack.danger { animation: pulseAttack .7s infinite alternate; }
@keyframes pulseAttack { to { box-shadow: 0 0 0 8px rgba(196,85,68,.08), 0 0 30px rgba(196,85,68,.27); } }

#quickbar {
  position: absolute; left: 50%; bottom: max(16px, env(safe-area-inset-bottom));
