.slot .slot-icon svg { width: 21px; height: 21px; }
.slot .slot-label { font: 6.5px/1 var(--mono); letter-spacing: .06em; color: #8e8877; }
.slot .slot-qty { position: absolute; top: 3px; right: 4px; font: 8px/1 var(--mono); color: var(--amber-bright); }
