  .portrait { width: 37px; height: 48px; font-size: 18px; }
  .char-name-row > span:first-child { font-size: 10px; max-width: 100px; }
  .prof-tag { font-size: 6px; padding: 2px 3px; }
  .health-line { gap: 4px; }
  .bar-label { font-size: 6px; }
  .bar-label svg { width: 9px; height: 9px; }
  .needs-mini { gap: 4px; }
  .need-mini svg { width: 8px; height: 8px; }
  .status-chips { left: 50px; bottom: -17px; }
  .status-chip { font-size: 6px; padding: 3px 4px; }
  .clock-panel { display: none; }
  .top-actions { gap: 3px; }
  .icon-btn { min-width: 38px; height: 39px; padding: 4px; }
  .icon-btn svg { width: 15px; height: 15px; }
  .icon-btn span { display: none; }
  .menu-btn { min-width: 34px; }
