/* ============================================================ PANELS */
.overlay {
  position: fixed; inset: 0; z-index: 30;
  display: flex; align-items: center; justify-content: center;
  padding: 20px;
  background: rgba(5, 7, 5, .55);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
  animation: overlayIn .15s ease-out;
}
@keyframes overlayIn { from { opacity: 0; } }
.panel {
  width: min(940px, 100%); max-height: min(760px, calc(100dvh - 40px));
  background:
    linear-gradient(160deg, rgba(25, 28, 22, .98), rgba(13, 16, 12, .99));
  border: 1px solid rgba(219, 203, 168, .2);
  box-shadow: 0 30px 80px rgba(0,0,0,.6);
  display: flex; flex-direction: column; position: relative;
}
.panel::before { content: ""; position: absolute; inset: 7px; border: 1px solid rgba(219,203,168,.045); pointer-events: none; }
.panel-head { display: flex; justify-content: space-between; align-items: center; padding: 16px 20px 12px; border-bottom: 1px solid var(--line); }
.panel-title-wrap { display: flex; flex-direction: column; gap: 5px; }
#panelKicker { font: 7.5px/1 var(--mono); letter-spacing: .23em; color: var(--amber); }
.panel-head h2 { font-family: var(--serif); font-weight: normal; font-size: 28px; line-height: 1; margin: 0; color: #eee5d2; }
.close-btn { width: 35px; height: 35px; border: 1px solid var(--line); display: grid; place-items: center; color: #948d7b; }
.close-btn:hover { border-color: var(--amber); color: var(--amber-bright); }
.close-btn svg { width: 17px; height: 17px; }
.panel-tabs { display: flex; gap: 2px; padding: 10px 20px 0; border-bottom: 1px solid var(--line); overflow-x: auto; scrollbar-width: none; }
.panel-tabs::-webkit-scrollbar { display: none; }
.tab {
  padding: 8px 13px 9px; border: 1px solid transparent; border-bottom: 0;
  font: 8px/1 var(--mono); letter-spacing: .13em; color: #878171;
  white-space: nowrap;
}
.tab.active { color: var(--amber-bright); border-color: var(--line); background: rgba(213,160,74,.06); position: relative; top: 1px; }
.panel-body { padding: 16px 20px; overflow-y: auto; flex: 1; min-height: 0; scrollbar-color: rgba(213,160,74,.35) transparent; }
.panel-body::-webkit-scrollbar { width: 7px; }
.panel-body::-webkit-scrollbar-thumb { background: rgba(213,160,74,.3); }
.panel-foot { padding: 10px 20px; border-top: 1px solid var(--line); display: flex; align-items: center; gap: 10px; min-height: 47px; font: 8px/1.3 var(--mono); color: #777264; }
.panel-foot .spacer { flex: 1; }

.inv-layout { display: grid; grid-template-columns: 1.35fr .85fr; gap: 18px; }
.inv-left { min-width: 0; }
.section-label { display: flex; justify-content: space-between; align-items: center; font: 7.5px/1 var(--mono); letter-spacing: .17em; color: #8c8675; margin-bottom: 8px; }
.section-label b { color: #b9b19d; font-weight: normal; }
.inv-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 5px; }
.item-card {
  min-height: 86px; padding: 7px; border: 1px solid var(--line);
  background: rgba(255,255,255,.012); display: flex; flex-direction: column;
  align-items: flex-start; gap: 4px; text-align: left; position: relative; overflow: hidden;
  transition: border-color .12s, background .12s;
}
.item-card:hover { border-color: rgba(213,160,74,.45); background: rgba(213,160,74,.045); }
.item-card.selected { border-color: var(--amber); background: rgba(213,160,74,.09); }
.item-card.equipped { border-color: rgba(109,154,174,.5); }
.item-ico { width: 30px; height: 30px; display: grid; place-items: center; color: var(--ic, #b6ae9a); }
.item-ico svg { width: 26px; height: 26px; }
.item-name { font-size: 8.5px; line-height: 1.15; color: #c8c0ac; margin-top: auto; }
.item-qty { position: absolute; top: 5px; right: 6px; font: 8px/1 var(--mono); color: var(--amber-bright); }
.item-tag { font: 6.5px/1 var(--mono); letter-spacing: .06em; color: #756f60; }
.weight-row { margin-top: 10px; }
.weight-row .mini-bar { height: 5px; }
.weight-row .mini-bar i { background: var(--amber); }
.weight-row .weight-label { display: flex; justify-content: space-between; font: 7px/1 var(--mono); color: #817a69; margin-bottom: 4px; }
.inv-side { border-left: 1px solid var(--line); padding-left: 18px; display: flex; flex-direction: column; gap: 14px; }
.equip-box { border: 1px solid var(--line); padding: 10px; background: rgba(0,0,0,.15); }
.equip-box h3 { font: 7px/1 var(--mono); letter-spacing: .16em; color: var(--amber); margin: 0 0 9px; }
.equip-line { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 5px 0; border-bottom: 1px dashed rgba(219,203,168,.08); font-size: 9.5px; color: #c1b9a4; }
.equip-line:last-child { border-bottom: 0; }
.equip-line span:last-child { font-size: 8px; color: #7f7968; }
.detail-card { border: 1px solid var(--line); padding: 12px; background: rgba(0,0,0,.18); }
.detail-card h3 { font-family: var(--serif); font-weight: normal; font-size: 17px; margin: 0 0 5px; color: #e1d8c4; }
.detail-card p { font-size: 9.5px; line-height: 1.6; color: #999281; margin: 0 0 10px; }
.detail-stats { display: flex; flex-wrap: wrap; gap: 5px; margin-bottom: 10px; }
.stat-pill { font: 7px/1 var(--mono); letter-spacing: .05em; color: #a89f8a; border: 1px solid var(--line); padding: 4px 6px; }
.actions-row { display: flex; gap: 6px; flex-wrap: wrap; }
.action-btn { border: 1px solid var(--line-strong); color: #cfc6b1; padding: 8px 11px; font: 8px/1 var(--mono); letter-spacing: .08em; background: rgba(255,255,255,.02); }
.action-btn:hover { border-color: var(--amber); color: var(--amber-bright); }
.action-btn.primary { background: var(--amber); color: #17170f; border-color: var(--amber); }
.action-btn.danger { color: #d58f7e; border-color: rgba(196,85,68,.4); }
.empty-note { padding: 34px 16px; text-align: center; color: #777264; font: 10px/1.6 var(--sans); border: 1px dashed var(--line); }

/* Loot */
.loot-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; }
.loot-head h3 { font-family: var(--serif); font-weight: normal; font-size: 20px; margin: 0; color: #e7deca; }
.loot-head span { font: 8px/1 var(--mono); color: #8c8675; }
.loot-list { display: flex; flex-direction: column; border: 1px solid var(--line); }
.loot-row { display: flex; align-items: center; gap: 10px; padding: 9px 11px; border-bottom: 1px solid rgba(219,203,168,.08); }
.loot-row:last-child { border-bottom: 0; }
.loot-row .item-ico { width: 24px; height: 24px; }
.loot-row .item-ico svg { width: 21px; height: 21px; }
.loot-name { flex: 1; font-size: 10.5px; color: #cbc3af; }
.loot-name small { display: block; color: #7b7566; font-size: 7.5px; margin-top: 2px; }
.loot-qty { font: 8px/1 var(--mono); color: var(--amber-bright); }
.loot-empty { padding: 30px 16px; text-align: center; color: #777264; font-size: 10px; }
.take-all { margin-top: 10px; display: flex; justify-content: space-between; align-items: center; }
.take-all span { font: 8px/1 var(--mono); color: #837d6d; }

/* Craft */
.craft-layout { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
.recipe { border: 1px solid var(--line); padding: 11px 12px; background: rgba(255,255,255,.012); display: flex; flex-direction: column; gap: 6px; }
.recipe.unavailable { opacity: .55; }
.recipe-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; }
.recipe-head h3 { font-size: 11px; margin: 0; color: #ddd4c0; font-weight: bold; }
.recipe-head span { font: 6.5px/1 var(--mono); color: var(--amber); border: 1px solid rgba(213,160,74,.25); padding: 3px 5px; white-space: nowrap; }
.recipe p { font-size: 8.5px; line-height: 1.45; color: #8f8878; margin: 0; }
.req-row { display: flex; flex-wrap: wrap; gap: 4px; }
.req { font: 7px/1 var(--mono); color: #a39b87; border: 1px solid var(--line); padding: 3px 5px; }
.req.missing { color: #c97c6c; border-color: rgba(196,85,68,.3); }
.req.station-ok { color: #9db77d; border-color: rgba(125,157,95,.35); }
.recipe-foot { display: flex; justify-content: space-between; align-items: center; margin-top: 2px; }
.recipe-foot small { font: 7px/1 var(--mono); color: #766f60; }
.craft-btn { border: 1px solid var(--amber); color: var(--amber-bright); padding: 6px 9px; font: 7px/1 var(--mono); letter-spacing: .08em; }
.craft-btn:hover { background: var(--amber); color: #17170f; }
.craft-btn:disabled { border-color: var(--line); color: #686354; cursor: not-allowed; }
.build-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
.build-card { border: 1px solid var(--line); padding: 11px; display: flex; flex-direction: column; gap: 7px; background: rgba(255,255,255,.012); }
.build-card h3 { font-size: 11px; margin: 0; color: #ddd4c0; }
.build-card p { font-size: 8.5px; line-height: 1.4; color: #8f8878; margin: 0; }
.build-card .req-row { margin-top: 1px; }

/* Skills */
.skills-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 7px 20px; }
.skill-row { display: flex; align-items: center; gap: 9px; padding: 7px 0; border-bottom: 1px dashed rgba(219,203,168,.08); }
.skill-glyph { width: 27px; height: 27px; display: grid; place-items: center; border: 1px solid var(--line); color: var(--amber); font: 13px/1 var(--serif); }
.skill-mid { flex: 1; min-width: 0; }
.skill-name-row { display: flex; justify-content: space-between; font-size: 9.5px; color: #c8c0ac; margin-bottom: 5px; }
.skill-name-row span:last-child { font: 8px/1 var(--mono); color: var(--amber-bright); }
.skill-xp { height: 3px; background: rgba(0,0,0,.45); }
.skill-xp i { display: block; height: 100%; background: linear-gradient(90deg, #7d6234, var(--amber)); }
.skill-desc { font-size: 7.5px; color: #777161; margin-top: 3px; }
.stats-strip { display: flex; flex-wrap: wrap; gap: 5px; margin-bottom: 14px; }
.stats-strip span { border: 1px solid var(--line); padding: 6px 8px; font: 7.5px/1 var(--mono); color: #989180; }
.stats-strip b { color: #cec5b0; font-weight: normal; }

/* Map */
.map-wrap { position: relative; display: flex; flex-direction: column; gap: 8px; }
#mapCanvas { width: 100%; aspect-ratio: 1.45; background: #0e110d; border: 1px solid var(--line); display: block; image-rendering: auto; }
.map-legend { display: flex; flex-wrap: wrap; gap: 12px; font: 7.5px/1 var(--mono); color: #8f8878; }
.map-legend span { display: flex; align-items: center; gap: 5px; }
.legend-dot { width: 7px; height: 7px; display: inline-block; }
.map-meta { position: absolute; top: 8px; right: 8px; background: rgba(10,12,9,.8); border: 1px solid var(--line); padding: 5px 7px; font: 7px/1 var(--mono); color: #a49c88; }
.map-note { font-size: 8.5px; color: #858071; line-height: 1.5; }

/* Journal */
.journal-grid { display: grid; grid-template-columns: 1.1fr .9fr; gap: 20px; }
.objective-list { display: flex; flex-direction: column; gap: 4px; }
.objective-item { display: flex; gap: 9px; align-items: flex-start; padding: 8px 9px; border: 1px solid rgba(219,203,168,.08); background: rgba(255,255,255,.01); }
.objective-item.done { opacity: .55; }
.obj-check { width: 16px; height: 16px; flex: 0 0 auto; border: 1px solid var(--line-strong); display: grid; place-items: center; font-size: 9px; color: transparent; }
.objective-item.done .obj-check { background: var(--green); border-color: var(--green); color: #10130f; }
.objective-item div { display: flex; flex-direction: column; gap: 2px; }
.objective-item b { font-size: 9.5px; color: #c7bfab; font-weight: normal; }
.objective-item small { font-size: 7.5px; color: #7e7869; }
.journal-stats { display: flex; flex-direction: column; gap: 0; border: 1px solid var(--line); }
.journal-stat { display: flex; justify-content: space-between; padding: 8px 10px; border-bottom: 1px solid rgba(219,203,168,.07); font-size: 9px; color: #999281; }
.journal-stat:last-child { border-bottom: 0; }
.journal-stat b { color: #d4cbb6; font-weight: normal; }
.tips { margin-top: 16px; font-size: 9px; line-height: 1.7; color: #898372; border-left: 2px solid rgba(213,160,74,.35); padding-left: 10px; }
.tips b { color: var(--amber); }

/* Pause / settings */
.pause-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.pause-actions { display: flex; flex-direction: column; gap: 6px; }
.pause-actions .action-btn { text-align: left; padding: 12px; }
.setting-row { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 9px 0; border-bottom: 1px solid rgba(219,203,168,.08); }
.setting-row label { font-size: 10px; color: #bdb5a0; }
.setting-row small { display: block; font-size: 7.5px; color: #7b7566; margin-top: 2px; }
.setting-row input[type=range] { width: 120px; accent-color: var(--amber); }
.setting-row select { background: #151812; border: 1px solid var(--line); color: #c8c0ac; padding: 6px; font-size: 9px; }
.pause-note { font: 8px/1.6 var(--mono); color: #6f6a5c; margin-top: 12px; }
.controls-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 5px 20px; font-size: 9px; color: #9a9381; }
.controls-grid div { display: flex; justify-content: space-between; gap: 8px; padding: 5px 0; border-bottom: 1px dashed rgba(219,203,168,.08); }
.controls-grid b { color: #d1c7b2; font: 8px/1 var(--mono); }

/* Death */
.death-screen { z-index: 60; background: radial-gradient(90% 80% at 50% 30%, rgba(48,22,18,.92), rgba(7,8,6,.98)); }
.death-grain { position: absolute; inset: 0; opacity: .3; background: repeating-linear-gradient(0deg, transparent 0 3px, rgba(0,0,0,.25) 3px 4px); pointer-events: none; }
.death-card { position: relative; z-index: 2; width: min(620px, calc(100% - 30px)); text-align: center; padding: 20px; }
.death-kicker { font: 8px/1 var(--mono); letter-spacing: .3em; color: #b76652; }
.death-card h1 { font-family: var(--serif); font-weight: normal; font-size: clamp(44px, 7vw, 80px); line-height: .83; margin: 18px 0; color: #e8ddc7; }
.death-card h1 em { color: #b95543; font-style: italic; }
.death-card > p { font-size: 11px; color: #9c9282; margin: 0 0 22px; line-height: 1.6; }
.death-stats { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px 20px; border-top: 1px solid rgba(219,203,168,.14); border-bottom: 1px solid rgba(219,203,168,.14); padding: 15px 10px; margin-bottom: 24px; font: 8px/1.6 var(--mono); color: #8c8574; }
.death-stats b { display: block; color: #d8cdb8; font-size: 14px; font-family: var(--serif); }
.death-actions { display: flex; flex-direction: column; gap: 8px; align-items: center; }
.death-actions .play-btn { width: min(300px, 100%); }
.death-actions .ghost-btn { width: min(300px, 100%); text-align: center; justify-content: center; }
.fade { position: fixed; inset: 0; z-index: 55; background: #050604; opacity: 0; pointer-events: none; transition: opacity .5s; }
.fade.on { opacity: 1; }

@media (max-width: 760px) {
  .overlay { padding: 8px; align-items: flex-end; }
  .panel { max-height: calc(100dvh - 16px); width: 100%; }
  .panel-head { padding: 12px 13px 9px; }
  .panel-head h2 { font-size: 22px; }
  .panel-body { padding: 12px 13px; }
  .panel-foot { padding: 8px 13px; }
  .panel-tabs { padding: 7px 13px 0; }
  .inv-layout { grid-template-columns: 1fr; gap: 12px; }
  .inv-side { border-left: 0; border-top: 1px solid var(--line); padding-left: 0; padding-top: 12px; }
  .inv-grid { grid-template-columns: repeat(4, 1fr); gap: 4px; }
  .item-card { min-height: 74px; padding: 5px; }
  .item-ico svg { width: 21px; height: 21px; }
  .item-name { font-size: 7.5px; }
  .craft-layout, .build-grid { grid-template-columns: 1fr; }
  .skills-grid { grid-template-columns: 1fr; }
  .journal-grid { grid-template-columns: 1fr; gap: 12px; }
  .pause-grid { grid-template-columns: 1fr; }
  .controls-grid { grid-template-columns: 1fr; }
  .death-card h1 { font-size: 47px; }
}

/* ==========================================================================
   CINZAS DE AURORA — an isometric survival sandbox.
   Procedural world, characters, weather, UI and audio. No external assets.
   ========================================================================== */
import {
  PROFESSIONS, DIFFICULTIES, ITEMS, RECIPES, BUILDABLES, CROPS, SKILLS,
  SKILL_LEVEL_XP, SAVE_KEY
} from './data.js';
import { createWorld, T, TILE_W, TILE_H, WALL_H } from './world.js';

const $ = (sel) => document.querySelector(sel);
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const lerp = (a, b, t) => a + (b - a) * t;
const dist = (ax, ay, bx, by) => Math.hypot(ax - bx, ay - by);
const TAU = Math.PI * 2;
const MIN_PER_SEC = 1.18;
const rnd = (a = 1) => Math.random() * a;
const rndi = (a, b) => Math.floor(a + Math.random() * (b - a + 1));
const esc = (s) => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmtTime = (minutes) => `${String(Math.floor(minutes / 60) % 24).padStart(2, '0')}:${String(Math.floor(minutes % 60)).padStart(2, '0')}`;
const smooth = (a, b, x) => { const t = clamp((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); };

const canvas = $('#game');
const ctx = canvas.getContext('2d', { alpha: false });

const G = {
  mode: 'menu', dead: false, started: false, paused: false,
  time: 0, last: 0, W: 0, H: 0, dpr: 1,
  zoom: 1.1, baseZoom: 1.1,
  cam: { x: 0, y: 0 },
  shake: 0, flash: 0, flashCooldown: 0,
  player: null, world: null,
  zombies: [], vehicles: [], structures: [], pickups: [],
  decals: [], corpses: [], particles: [], floats: [], rain: [],
  discovered: null, foundLocations: new Set(), containers: new Map(),
  objectiveFlags: {}, stats: {},
  target: null, fishing: null, placing: null, buildTarget: null,
  selectedProfession: 'survivor', selectedDifficulty: 'normal', playerName: 'Aurora',
  timeOfDay: { day: 1, minutes: 16 * 60 + 40 },
  weather: { type: 'clear', label: 'Limpo', temp: 19, targetTemp: 19, wind: 2, next: 0, intensity: 0 },
  settings: { volume: 0.6, quality: 'medium', gore: true, autosave: true },
  ui: { panel: null, tab: 'craft', selected: null, container: null, farmPlot: null },
  uid: 1, saveTimer: 0, hudTimer: 0, discoverTimer: 0, spawnTimer: 0, ambientTimer: 0,
  noiseTimer: 0, footTimer: 0, frame: 0, lastSave: 0,
  audioReady: false, trail: []
};

const DIFF = () => DIFFICULTIES[G.selectedDifficulty] || DIFFICULTIES.normal;
const IN_BAG = (id) => G.player?.inventory.some(e => e.id === id);
const entryOf = (id) => G.player?.inventory.find(e => e.id === id);
const countOf = (id) => G.player ? G.player.inventory.filter(e => e.id === id).reduce((n, e) => n + e.qty, 0) : 0;

/* ---------------------------------------------------------------- audio */
const AudioFX = {
  ctx: null, master: null, rainGain: null, rainSrc: null, noiseBuf: null,
  init() {
    if (this.ctx) return;
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = G.settings.volume;
      this.master.connect(this.ctx.destination);
      const len = this.ctx.sampleRate * 2;
      const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const data = buf.getChannelData(0);
      for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
      this.noiseBuf = buf;
      const src = this.ctx.createBufferSource();
      src.buffer = buf; src.loop = true;
      const filt = this.ctx.createBiquadFilter();
      filt.type = 'lowpass'; filt.frequency.value = 900;
      const gain = this.ctx.createGain(); gain.gain.value = 0;
