  setVolume(v) { if (this.master) this.master.gain.value = v; },
  tone(freq = 440, dur = .08, vol = .12, type = 'sine', slide = 0) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator(); const g = this.ctx.createGain();
