  x.fillStyle = '#f0c16c'; x.beginPath(); x.moveTo(0, -5); x.lineTo(4, 4); x.lineTo(0, 2.4); x.lineTo(-4, 4); x.closePath(); x.fill();
  x.restore();
  x.strokeStyle = 'rgba(213,160,74,.3)'; x.lineWidth = 1; x.strokeRect(ox, oy, n * s, n * s);
}
