204:     return 0;
205:   }
206:   if (per > 0) qty = Math.min(qty, Math.max(1, Math.floor((cap - current) / per)));
207:   if (d.stack || d.cat === 'material' || d.cat === 'food' || d.cat === 'drink' || d.cat === 'medical') {
208:     const same = p.inventory.find(e => e.id === id && (e.durability == null || durability == null));
209:     if (same) {
210:       const max = d.stack || 20;
211:       const room = max - same.qty;
212:       const move = Math.min(room, qty);
213:       same.qty += move; added += move; qty -= move;
214:       if (qty <= 0) { if (!silent) { AudioFX.pickup(); } return added; }
215:     }
216:   }
217:   while (qty > 0) {
218:     const d2 = itemDef(id);
219:     const chunk = Math.min(qty, d2.stack || 1);
220:     p.inventory.push(makeEntry(id, chunk, durability));
221:     added += chunk; qty -= chunk;
222:   }
223:   if (added && !silent) AudioFX.pickup();
224:   return added;
225: }
226: function removeItem(id, qty = 1) {
