function renderLighting() {
  const night = nightFactor();
  const p = G.player;
  const inside = playerInsideBuilding();
  const weatherDim = (G.weather.type === 'storm' ? .16 : G.weather.type === 'rain' ? .1 : G.weather.type === 'fog' ? .07 : 0);
  let dark = night * .68 + weatherDim;
  if (inside) dark *= .86;
